    const folderPaths = new Set<string>()
    for (const filePath of files) {
        const segments = filePath.split('/')
        segments.pop()
        let currentPath = ''
        for (const segment of segments) {
            currentPath = currentPath.length === 0 ? segment : `${currentPath}/${segment}`
